void stat(int a[], int n, int *pmax, int *pmin, double *pavg)
{
    int i, sum = 0;
    *pmax = a[0];
    *pmin = a[0];
    for (i = 0; i < n; i++)
    {
        if (a[i] > *pmax) *pmax = a[i];
        if (a[i] < *pmin) *pmin = a[i];
        sum += a[i];
    }
    *pavg = 1.0 * sum / n;
}
