    convert(ch, s);
    printf("%s\n", s);
    return 0;
}

#include <stdio.h>
int main()
{
    int n, i;
    scanf("%d", &n);
    for (i = 7; i >= 0; i--)
        printf("%d", (n >> i) & 1);
